SELECT ID, USERNAME, EMAIL, ROLE, STATUS, CREATE_DATE, UPDATE_DATE
FROM TB_USER


        AND USERNAME LIKE CONCAT('%', #{username}, '%')


        AND EMAIL LIKE CONCAT('%', #{email}, '%')


        AND ROLE = #{role}


        AND STATUS = #{status}


ORDER BY CREATE_DATE DESC

    LIMIT #{limit}


    OFFSET #{offset}

SELECT COUNT(*) FROM TB_USER


        AND USERNAME LIKE CONCAT('%', #{username}, '%')


        AND EMAIL LIKE CONCAT('%', #{email}, '%')


        AND ROLE = #{role}


        AND STATUS = #{status}

